                  input.setAttribute("aria-invalid", "true");
                });
                form.querySelector('input[name="notification-preference"]').focus();
                return;
              }
              error.textContent = "";
              form.querySelectorAll('input[name="notification-preference"]').forEach((input) => {
                input.removeAttribute("aria-invalid");
              });
              status.textContent = `Saved: ${selected.value}.`;
            },
          },
          h(
            "div",
            { className: "form-field" },
            h(
              "fieldset",
              {},
              h("legend", {}, "How do you prefer to receive notifications?"),
              h("p", { className: "help-text", id: "notification-help" }, "Choose one option."),
              error,
              h(
                "ul",
                { className: "options" },
                RadioOption({
                  id: "notification-email",
                  value: "Email",
                  label: "Email",
                  required: true,
                  describedBy: "notification-help notification-error",
                }),
                RadioOption({
                  id: "notification-sms",
                  value: "SMS",
                  label: "SMS",
                  describedBy: "notification-help notification-error",
                }),
                RadioOption({
                  id: "notification-push",
                  value: "Push Notifications",
                  label: "Push Notifications",
                  describedBy: "notification-help notification-error",
                }),
              ),
            ),
          ),
          h(
            "div",
            { className: "actions" },
            h("button", { className: "button", type: "submit" }, "Submit"),
          ),
          status,
        );

        return h(
          "main",
          { id: "main-content", className: "page" },
          h(
            "section",
            { className: "card", "aria-labelledby": "page-title" },
            h(
              "header",
              { className: "card__header" },
              h("h1", { id: "page-title" }, "Notification settings"),
              h("p", { className: "subtitle" }, "Tell us how you'd like to hear from us."),
            ),
            h("div", { className: "card__body" }, form),
          ),
        );
      };

      document.getElementById("root").append(NotificationPreferencesForm());
    </script>
