              radio.removeAttribute("aria-invalid");
            });
          });
        });

        return h(
          "main",
          { id: "main-content", className: "page" },
          h(
            "section",
            { className: "card", "aria-labelledby": "page-title" },
            h(
              "header",
              { className: "card__header" },
              h("h1", { id: "page-title" }, "Notification settings"),
              h("p", { className: "subtitle" }, "Tell us how you'd like to hear from us."),
            ),
            h("div", { className: "card__body" }, form),
          ),
